import{_ as t,c as i,o as r,ag as a}from"./chunks/framework.ARG558ZT.js";const g=JSON.parse('{"title":"What do you think, who is responsible for write unit tests?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Testing/What_do_you_think,_who_is_responsible_for_write_unit_tests.md","filePath":"senior_growth/Testing/What_do_you_think,_who_is_responsible_for_write_unit_tests.md"}'),s={name:"senior_growth/Testing/What_do_you_think,_who_is_responsible_for_write_unit_tests.md"};function n(o,e,l,d,h,c){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="what-do-you-think-who-is-responsible-for-write-unit-tests" tabindex="-1">What do you think, who is responsible for write unit tests? <a class="header-anchor" href="#what-do-you-think-who-is-responsible-for-write-unit-tests" aria-label="Permalink to “What do you think, who is responsible for write unit tests?”">​</a></h1><h1 id="🧪-responsibility-for-writing-unit-tests" tabindex="-1">🧪 Responsibility for Writing Unit Tests <a class="header-anchor" href="#🧪-responsibility-for-writing-unit-tests" aria-label="Permalink to “🧪 Responsibility for Writing Unit Tests”">​</a></h1><p><strong>Unit tests</strong> are a fundamental part of software quality, and <strong>responsibility should be shared across the team</strong>, but primarily it falls on <strong>developers writing the code</strong>.</p><hr><h2 id="_1️⃣-primary-responsibility-developers" tabindex="-1">1️⃣ Primary Responsibility: Developers <a class="header-anchor" href="#_1️⃣-primary-responsibility-developers" aria-label="Permalink to “1️⃣ Primary Responsibility: Developers”">​</a></h2><ul><li><strong>Who:</strong> The engineer who writes the feature or module</li><li><strong>Why:</strong><ul><li>They know the <strong>implementation details and expected behavior</strong></li><li>Writing tests alongside the code ensures <strong>immediate feedback</strong></li><li>Aligns with <strong>TDD / FIRST principles</strong></li></ul></li><li><strong>Benefits:</strong><ul><li>Fewer bugs in production</li><li>Faster debugging and refactoring</li><li>Encourages clean, modular code design</li></ul></li></ul><hr><h2 id="_2️⃣-secondary-responsibility-team-code-review" tabindex="-1">2️⃣ Secondary Responsibility: Team / Code Review <a class="header-anchor" href="#_2️⃣-secondary-responsibility-team-code-review" aria-label="Permalink to “2️⃣ Secondary Responsibility: Team / Code Review”">​</a></h2><ul><li><strong>Code reviewers / peers</strong> should ensure: <ul><li>Tests exist for new features</li><li>Tests are meaningful and follow best practices</li><li>Coverage of edge cases and critical paths</li></ul></li><li><strong>Pair programming / mob programming</strong> can also help maintain test quality</li></ul><hr><h2 id="_3️⃣-other-stakeholders" tabindex="-1">3️⃣ Other Stakeholders <a class="header-anchor" href="#_3️⃣-other-stakeholders" aria-label="Permalink to “3️⃣ Other Stakeholders”">​</a></h2><ul><li><strong>QA / Test Engineers:</strong><ul><li>Typically focus on <strong>integration and E2E tests</strong>, but may contribute unit tests in some teams</li></ul></li><li><strong>Tech Leads / Architects:</strong><ul><li>Ensure <strong>testing culture is enforced</strong></li><li>Set coverage standards and guidelines</li></ul></li></ul><hr><h2 id="_4️⃣-best-practices" tabindex="-1">4️⃣ Best Practices <a class="header-anchor" href="#_4️⃣-best-practices" aria-label="Permalink to “4️⃣ Best Practices”">​</a></h2><ol><li><strong>Write tests as you code</strong> (TDD or alongside feature development)</li><li><strong>Test critical paths first</strong></li><li><strong>Review unit tests in PRs</strong> like production code</li><li><strong>Maintain ownership</strong>: developers investigate regressions and fix production behavior or obsolete expectations according to the requirement; do not weaken tests merely to get green</li></ol><hr><h3 id="✅-key-takeaways" tabindex="-1">✅ Key Takeaways <a class="header-anchor" href="#✅-key-takeaways" aria-label="Permalink to “✅ Key Takeaways”">​</a></h3><ul><li><strong>Developers are primarily responsible</strong> for unit tests.</li><li><strong>QA and team leads</strong> support and enforce quality and coverage.</li><li><strong>Ownership matters:</strong> the author supplies behavior evidence and reviewers challenge assumptions; proximity alone does not guarantee quality.</li></ul><blockquote><p>💡 Senior Tip:<br> Unit tests are <strong>part of the definition of done (DoD)</strong> for a feature. No code should be merged without meaningful tests.</p></blockquote><h2 id="worked-review-responsibility" tabindex="-1">Worked review responsibility <a class="header-anchor" href="#worked-review-responsibility" aria-label="Permalink to “Worked review responsibility”">​</a></h2><p>The <a href="./TDD_-_pros_and_cons(red,_green,_refactor).html#config-tdd">configuration-limit TDD fixture</a> records an authored review finding: a first passing parser suite needed a trailing-newline case because JavaScript <code>$</code> can match before a final terminator. The author owns the input contract and repair; a reviewer asks whether “no whitespace” includes newline, requests an observable negative case, and checks the actual implementation/diff rather than accepting the pass count. This is a constructed study record with actual local checks, not a claim that another person performed a review.</p><p>The <a href="./../../ai-assisted-engineering/traceability-and-evaluation.html">AI-assisted engineering evidence route</a> adds requirement-to-test mapping and detected defect variants. Independent human review and learner practice remain separate; a model&#39;s self-review is not evidence that a peer approved a change. QA can contribute unit, integration or exploratory tests according to expertise; ownership is collaborative rather than a prohibition on who may write a test.</p><h2 id="separate-practice" tabindex="-1">Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “Separate practice”">​</a></h2><p>Use the <a href="./../../practice/engineering/testing/What_do_you_think%2C_who_is_responsible_for_write_unit_tests.html">focused acceptance and evidence requirements</a>. All learner practice remains outstanding.</p>',24)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
